import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to exhibit specific ELA features.
    """
    n = x.shape[0]

    # Quadratic bowl with a bias
    f = np.sum(x**2)

    # Add linear terms to introduce skewness and correlation
    f += 0.1 * np.sum(x)

    # Add interaction terms to increase complexity
    for i in range(n):
        for j in range(i + 1, n):
            f += 0.05 * x[i] * x[j]

    # Apply power transformation to some dimensions
    for i in range(n):
        if i % 2 == 0:
            f += 0.01 * np.abs(x[i])**3

    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (5,):
        raise ValueError(f"Input x must be a numpy array of shape (5,), but got {x.shape}")

    x_scaled = x / 5

    quad_term = 0.5 * np.sum(x_scaled**2)
    for i in range(5):
        for j in range(i + 1, 5):
            quad_term += 0.1 * (x_scaled[i] * x_scaled[j])

    linear_term = np.sum(x_scaled * np.array([0.2, -0.3, 0.15, 0.05, -0.1]))
    skewness_term = 0.05 * np.sum((x_scaled**3) * np.sin(x_scaled * np.pi * 2))

    fitness = quad_term + linear_term + skewness_term
    fitness = np.sign(fitness) * np.abs(fitness)**0.7
    modulation_term = 0.1 * np.sum(np.cos(x_scaled * np.pi))

    return float(fitness + modulation_term)

