import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (5,):
        raise ValueError(f"Input x must be a numpy array of shape (5,), but got {x.shape}")

    x_scaled = x / 5

    quintic_term = np.sum(0.1 * x_scaled**5 - 0.3 * x_scaled**3 + 0.2 * x_scaled)

    interaction_term = 0.0
    for i in range(5):
        for j in range(i + 1, 5):
            interaction_term += 0.05 * x_scaled[i]**2 * x_scaled[j]**2

    sin_modulation = np.sum(0.2 * np.sin(2 * np.pi * x_scaled))

    arctan_scaling = np.sum(0.1 * np.arctan(x_scaled * np.array([1.0, 1.5, 2.0, 2.5, 3.0])))

    fitness = quintic_term + interaction_term + sin_modulation + arctan_scaling
    fitness = np.log(1 + np.abs(fitness))

    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (5,):
        raise ValueError(f"Input x must be a numpy array of shape (5,), but got {x.shape}")

    x_scaled = x / 5

    quad_term = 0.5 * np.sum(x_scaled**2 * np.array([1.1, 0.9, 1.2, 0.8, 1.05]))
    for i in range(5):
        for j in range(i + 1, 5):
            quad_term += 0.1 * (x_scaled[i] * x_scaled[j])

    linear_term = np.sum(x_scaled * np.array([0.2, -0.3, 0.15, 0.05, -0.1]))
    skewness_term = 0.15 * np.sum(np.arctan(x_scaled**3) * np.sin(x_scaled * np.pi))

    fitness = quad_term + linear_term + skewness_term
    fitness = np.sign(fitness) * np.abs(fitness)**0.7
    modulation_term = 0.1 * np.sum(np.cos(x_scaled * np.pi * np.array([1.0, 0.8, 1.2, 0.9, 1.1])))

    return float(fitness + modulation_term)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (5,):
        raise ValueError(f"Input x must be a numpy array of shape (5,), but got {x.shape}")

    x_scaled = x / 5

    quad_term = 0.3 * np.sum(x_scaled**2)

    interaction_term = 0
    for i in range(5):
        for j in range(i + 1, 5):
            interaction_term += 0.05 * (i + j + 1) * x_scaled[i] * x_scaled[j]

    sine_modulation = 0.2 * np.sum(np.sin(2 * np.pi * x_scaled))
    softplus_warp = 0.1 * np.sum(np.log(1 + np.exp(5 * x_scaled)))

    rational_warp = 0
    for i in range(5):
        rational_warp += (0.1 * (i+1) * x_scaled[i]) / (1 + abs(x_scaled[i]))

    dimension_weights = np.array([0.8, 1.2, 0.9, 1.1, 1.0])

    final_fitness = np.sum(dimension_weights * (quad_term + interaction_term)) + sine_modulation + softplus_warp + rational_warp


    return float(final_fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    x_scaled = x / 5
    quad_term = np.sum(x_scaled**2)
    modulation_term = np.sum(np.sin(x_scaled * np.pi))
    skew_sigmoid = 1 / (1 + np.exp(-8 * x_scaled[0]))

    # Dimension-weighted logarithmic barrier term
    log_barrier = 0.0
    for i in range(len(x)):
        if x_scaled[i] < 1 and x_scaled[i] > -1:
          log_barrier += (i + 1) * np.log(1 - x_scaled[i]**2) #np.log is the new mathematical operation

    return float((quad_term + 0.2 * modulation_term) * skew_sigmoid - 0.05 * log_barrier)
